import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int[] fact = new int[10];
        fact[0] = 1;
        for (int i = 1; i <= 9; i++) fact[i] = fact[i - 1] * i;
        String s = Long.toString(n);
        int digits = s.length();
        long arm = 0, strong = 0;
        for (int i = 0; i < digits; i++) {
            int d = s.charAt(i) - '0';
            long p = 1;
            for (int k = 0; k < digits; k++) p *= d;
            arm += p;
            strong += fact[d];
        }
        long divSum = n > 1 ? 1 : 0;
        for (long d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                divSum += d;
                if (d != n / d) divSum += n / d;
            }
        }
        List<String> res = new ArrayList<>();
        if (arm == n) res.add("ARMSTRONG");
        if (strong == n) res.add("STRONG");
        if (divSum == n) res.add("PERFECT");
        System.out.println(res.isEmpty() ? "NONE" : String.join(" ", res));
    }
}

