import sys, math

n = int(sys.stdin.readline().strip())
s = str(n)
k = len(s)
arm = sum(int(c) ** k for c in s) == n
strong = sum(math.factorial(int(c)) for c in s) == n
div_sum = 1 if n > 1 else 0
d = 2
while d * d <= n:
    if n % d == 0:
        div_sum += d
        if d != n // d:
            div_sum += n // d
    d += 1
perfect = (div_sum == n)
out = []
if arm: out.append('ARMSTRONG')
if strong: out.append('STRONG')
if perfect: out.append('PERFECT')
print(' '.join(out) if out else 'NONE')

