import java.util.*;

public class Main {
    static long gcd(long a, long b) {
        while (b != 0) { long t = a % b; a = b; b = t; }
        return a;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long g = sc.nextLong();
        long l = g;
        for (int i = 1; i < n; i++) {
            long v = sc.nextLong();
            g = gcd(g, v);
            l = (l / gcd(l, v)) * v;
        }
        System.out.println(g + " " + l);
    }
}
